import { useState, useEffect } from "react";
import { initializeApp, getApps } from "firebase/app";
import { getFirestore, doc, getDoc } from "firebase/firestore";
import { setDoc } from "./fireGuard";

const firebaseConfig = {
  apiKey: "AIzaSyDLMwBqccgWDk7VFQdLYKuLNXWtkNn5WGA",
  authDomain: "moklog-checktest.firebaseapp.com",
  projectId: "moklog-checktest",
  storageBucket: "moklog-checktest.firebasestorage.app",
  messagingSenderId: "390165325023",
  appId: "1:390165325023:web:3147cd333503916b0d756a"
};
const fbApp = getApps().length ? getApps()[0] : initializeApp(firebaseConfig);
const db = getFirestore(fbApp);

const COL = "ronda_vspp";
const MAPA_B64 = "";
const SLOTS_DEFAULT = ["06:00","07:00","08:00","09:00","10:00","11:00","12:00","13:00","14:00","15:00","16:00","17:00","18:00","19:00","20:00"];


function todayStr(){ return new Date().toLocaleDateString("sv-SE"); }
function nowTime(){ const d=new Date(); return d.getHours().toString().padStart(2,"0")+":"+d.getMinutes().toString().padStart(2,"0"); }
function fmtDate(d){ if(!d) return "--"; try{ return new Date(d+"T12:00:00").toLocaleDateString("pt-BR"); }catch{ return d; } }

async function loadRondas(projectId){
  try{ const s=await getDoc(doc(db,COL,projectId)); if(s.exists()){ const d=s.data(); try{localStorage.setItem("ronda_vspp_"+projectId,JSON.stringify(d));}catch(e){} return d; } }catch(e){}
  try{ const l=localStorage.getItem("ronda_vspp_"+projectId); if(l) return JSON.parse(l); }catch(e){}
  return { slots: SLOTS_DEFAULT, registros: [] };
}
async function saveRondas(projectId, data){
  try{ await setDoc(doc(db,COL,projectId),{...data,updatedAt:new Date().toISOString()}); }catch(e){ console.error(e); }
  try{ localStorage.setItem("ronda_vspp_"+projectId,JSON.stringify(data)); }catch(e){}
}
async function loadEquipe(projectId){
  try{ const s=await getDoc(doc(db,"equipes",projectId)); if(s.exists()) return s.data().colaboradores||[]; }catch(e){}
  try{ const l=localStorage.getItem("equipe_"+projectId); if(l) return JSON.parse(l).colaboradores||[]; }catch(e){}
  return [];
}

function getS(dark){
  return {
    page:    {minHeight:"100vh",background:dark?"#04080f":"#f1f5f9",display:"flex",justifyContent:"center",padding:"0 0 80px",fontFamily:"'Segoe UI',system-ui,sans-serif"},
    wrap:    {width:"100%",maxWidth:480,display:"flex",flexDirection:"column"},
    card:    {background:dark?"#060c18":"#fff",border:`1px solid ${dark?"#0f172a":"#e2e8f0"}`,borderRadius:12,padding:"14px 16px"},
    btn:     {background:"linear-gradient(135deg,#0f6e56,#065f46)",color:"#fff",border:"none",borderRadius:10,padding:"13px 16px",fontSize:14,fontWeight:700,cursor:"pointer",width:"100%",display:"flex",alignItems:"center",justifyContent:"center",gap:8},
    btnSec:  {background:dark?"#060c18":"#f8fafc",color:dark?"#94a3b8":"#64748b",border:`1px solid ${dark?"#0f172a":"#e2e8f0"}`,borderRadius:10,padding:"11px 16px",fontSize:13,fontWeight:600,cursor:"pointer",width:"100%",display:"flex",alignItems:"center",justifyContent:"center"},
    btnSm:   {background:dark?"#020510":"#f8fafc",border:`1px solid ${dark?"#0f172a":"#e2e8f0"}`,color:dark?"#94a3b8":"#64748b",borderRadius:6,padding:"5px 10px",fontSize:11,cursor:"pointer",fontWeight:600},
    backBtn: {background:"transparent",border:`1px solid ${dark?"#0f172a":"#e2e8f0"}`,color:dark?"#94a3b8":"#64748b",borderRadius:7,padding:"7px 12px",fontSize:12,cursor:"pointer",flexShrink:0,fontWeight:600},
    inp:     {width:"100%",background:dark?"#020510":"#fff",border:`1px solid ${dark?"#0f172a":"#cbd5e1"}`,borderRadius:7,color:dark?"#e2e8f0":"#1e293b",padding:"10px 12px",fontSize:13,boxSizing:"border-box",outline:"none"},
    lbl:     {display:"block",fontSize:11,color:dark?"#94a3b8":"#64748b",fontWeight:700,marginBottom:4,textTransform:"uppercase",letterSpacing:.5},
    txt:     {color:dark?"#f1f5f9":"#0f172a"},
    txt2:    {color:dark?"#94a3b8":"#64748b"},
  };
}

function gerarPDFRondaVSPP(project, reg, todosRegistros){
  const hoje = new Date().toLocaleDateString("pt-BR");
  const slots = reg.slots || SLOTS_DEFAULT;
  const feitos   = slots.filter(h=>(reg.marcacoes||{})[h]?.status==="feito").length;
  const naoFeito = slots.filter(h=>(reg.marcacoes||{})[h]?.status==="nao_feito").length;
  const pendente = slots.filter(h=>!(reg.marcacoes||{})[h]).length;
  const pct      = slots.length ? Math.round((feitos/slots.length)*100) : 0;

  const zoneRows = slots.map(h=>{
    const m=(reg.marcacoes||{})[h];
    const st=m?.status||"pendente";
    const cfg=st==="feito"?{label:"Feito",color:"#15803d",bg:"#dcfce7"}:
               st==="nao_feito"?{label:"Não feito",color:"#dc2626",bg:"#fee2e2"}:
               {label:"Pendente",color:"#94a3b8",bg:"#f1f5f9"};
    return `<tr style="background:${st==="nao_feito"?"#fff8f8":"#fff"}">
      <td style="font-weight:700;text-align:center">${h}</td>
      <td><span style="background:${cfg.bg};color:${cfg.color};padding:2px 10px;border-radius:4px;font-size:11px;font-weight:700">${cfg.label}</span></td>
      <td style="font-size:11px;color:#64748b">${m?.obs||"—"}</td>
      <td style="font-size:11px;color:#64748b">${m?.hora||"—"}</td>
    </tr>`;
  }).join("");

  const historico=(todosRegistros||[]).filter(r=>r.data!==reg.data).slice(-7);
  const histRows=historico.map(r=>{
    const tot=(r.slots||SLOTS_DEFAULT).length;
    const f=Object.values(r.marcacoes||{}).filter(m=>m.status==="feito").length;
    const nf=Object.values(r.marcacoes||{}).filter(m=>m.status==="nao_feito").length;
    const kmTxt=(r.kmInicial||r.kmFinal)?(r.kmInicial?"Ini: "+r.kmInicial:"")+(r.kmInicial&&r.kmFinal?" · ":"")+(r.kmFinal?"Fim: "+r.kmFinal:""):"—";
    return `<tr>
      <td style="font-weight:700">${fmtDate(r.data)}</td>
      <td>${r.executor||"—"}</td>
      <td style="text-align:center;font-weight:700;color:#15803d">${f}</td>
      <td style="text-align:center;font-weight:700;color:#dc2626">${nf}</td>
      <td style="text-align:center;color:#94a3b8">${tot-f-nf}</td>
      <td style="font-size:11px">${kmTxt}</td>
    </tr>`;
  }).join("");

  const kmPercorrido = reg.kmInicial&&reg.kmFinal
    ? Math.abs(parseFloat(reg.kmFinal)-parseFloat(reg.kmInicial)).toFixed(1)+" km"
    : "—";

  const html = `<!DOCTYPE html>
<html lang="pt-BR"><head><meta charset="UTF-8">
<title>Ronda VSPP — ${project.id} — ${fmtDate(reg.data)}</title>
<style>
  *{box-sizing:border-box;margin:0;padding:0;-webkit-print-color-adjust:exact;print-color-adjust:exact;color-adjust:exact}
  body{font-family:'Segoe UI',Arial,sans-serif;background:#f8fafc;padding:20px;color:#1e293b;font-size:13px}
  .header{background:linear-gradient(135deg,#1a1040,#0f6e56);color:#fff;padding:18px 22px;border-radius:12px;margin-bottom:14px;display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:10px}
  .section{background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:14px 16px;margin-bottom:12px}
  .section-title{font-size:11px;font-weight:800;color:#475569;text-transform:uppercase;letter-spacing:.8px;border-bottom:1px solid #f1f5f9;padding-bottom:7px;margin-bottom:10px}
  .kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:12px}
  .kpi{background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:12px;text-align:center}
  .kpi-val{font-size:24px;font-weight:900}
  .kpi-lbl{font-size:9px;color:#64748b;font-weight:700;text-transform:uppercase;margin-top:3px}
  .km-box{background:#f0fdf4;border:1px solid #22c55e33;border-radius:8px;padding:10px 16px;display:flex;gap:24px;margin-bottom:12px}
  .km-item label{font-size:9px;color:#64748b;text-transform:uppercase;font-weight:700;display:block;margin-bottom:2px}
  .km-item span{font-size:18px;font-weight:900;color:#0f6e56}
  table{width:100%;border-collapse:collapse;font-size:12px}
  th{background:#1e293b;color:#fff;padding:7px 10px;text-align:left;font-size:11px}
  td{padding:6px 10px;border-bottom:1px solid #f1f5f9}
  .grid-2{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px}
  .footer{text-align:center;margin-top:14px;font-size:10px;color:#94a3b8;border-top:1px solid #e2e8f0;padding-top:10px}
  @media print{body{padding:8px}@page{margin:10mm;size:A4 landscape}.no-print{display:none}*{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}}
</style></head><body>
<div class="no-print" style="text-align:center;margin-bottom:14px">
  <button onclick="window.print()" style="background:#0f6e56;color:#fff;border:none;border-radius:8px;padding:10px 28px;font-size:14px;font-weight:700;cursor:pointer">🖨️ Imprimir / Salvar PDF</button>
</div>
<div class="header">
  <div>
    <p style="font-size:10px;opacity:.7;text-transform:uppercase;letter-spacing:.8px;margin-bottom:3px">Moked Consulting Security</p>
    <h1 style="font-size:18px;font-weight:900;margin-bottom:3px">🚗 Ronda VSPP — Turno Diurno</h1>
    <p style="font-size:12px;opacity:.85">${project.id} — Golgi Cajamar · ${fmtDate(reg.data)}</p>
  </div>
  <div style="text-align:right;font-size:11px;opacity:.8">
    <div>Gerado em ${hoje}</div>
    <div style="margin-top:2px">Executor: <strong style="color:#fff">${reg.executor||"—"}</strong></div>
    <div>José Fonseca — Moked Consulting</div>
  </div>
</div>

<div class="kpis">
  <div class="kpi"><div class="kpi-val" style="color:#15803d">${feitos}</div><div class="kpi-lbl">Feitas</div></div>
  <div class="kpi"><div class="kpi-val" style="color:#dc2626">${naoFeito}</div><div class="kpi-lbl">Não Feitas</div></div>
  <div class="kpi"><div class="kpi-val" style="color:#94a3b8">${pendente}</div><div class="kpi-lbl">Pendentes</div></div>
  <div class="kpi"><div class="kpi-val" style="color:#0f6e56">${pct}%</div><div class="kpi-lbl">Executado</div></div>
</div>

${(reg.kmInicial||reg.kmFinal)?`<div class="km-box">
  ${reg.kmInicial?`<div class="km-item"><label>KM Início (1ª Ronda)</label><span>${reg.kmInicial} km</span></div>`:""}
  ${reg.kmFinal?`<div class="km-item"><label>KM Fim (Última Ronda)</label><span>${reg.kmFinal} km</span></div>`:""}
  ${reg.kmInicial&&reg.kmFinal?`<div class="km-item"><label>KM Percorrido</label><span>${kmPercorrido}</span></div>`:""}
</div>`:""}

<div class="grid-2">
  <div class="section" style="margin-bottom:0">
    <div class="section-title">🗺️ Rota de Ronda VSPP — P601 Golgi Cajamar</div>
    <img src="data:image/jpeg;base64,${MAPA_B64}" alt="Rota de Ronda VSPP" style="width:100%;border-radius:6px"/>
  </div>
  <div class="section" style="margin-bottom:0">
    <div class="section-title">📋 Registro por Horário</div>
    <table><thead><tr><th>Horário</th><th>Status</th><th>Observação</th><th>Hora real</th></tr></thead>
    <tbody>${zoneRows}</tbody></table>
  </div>
</div>

${historico.length?`<div class="section" style="margin-top:12px">
  <div class="section-title">📈 Histórico — Últimos ${historico.length} Dia(s)</div>
  <table><thead><tr><th>Data</th><th>Executor</th><th style="text-align:center">✓ Feitas</th><th style="text-align:center">✗ Não feitas</th><th style="text-align:center">Pendentes</th><th>KM</th></tr></thead>
  <tbody>${histRows}</tbody></table>
</div>`:""}

<div class="footer">
  <div>MokLog CheckTest © Moked Consulting Security · Ronda VSPP — Turno Diurno</div>
  <div style="margin-top:3px">${project.id} — Golgi Cajamar · ${fmtDate(reg.data)}</div>
</div></body></html>`;

  const blob=new Blob([html],{type:"text/html"});
  const url=URL.createObjectURL(blob);
  const a=document.createElement("a");
  a.href=url; a.download=`ronda_vspp_P601_${reg.data||"sem-data"}.html`;
  a.click(); URL.revokeObjectURL(url);
}

export default function RondaVSPP({ project, onBack, dark, sharedAuth, onAuthGranted }){
  const S=getS(dark);
  const [loading,setLoading]=useState(true);
  const [saving,setSaving]=useState(false);
  const [data,setData]=useState({slots:SLOTS_DEFAULT,registros:[]});
  const [equipe,setEquipe]=useState([]);
  const [diaAtual,setDiaAtual]=useState(null);
  const [screen,setScreen]=useState("list");
  const [confirmDelSlot,setConfirmDelSlot]=useState(null);
  const adminAuth=sharedAuth==="admin";

  useEffect(()=>{
    Promise.all([loadRondas(project.id),loadEquipe(project.id)]).then(([r,e])=>{
      setData(r); setEquipe(e.filter(c=>c.status==="ativo")); setLoading(false);
    });
  },[project.id]);

  const save=async(newData)=>{ setData(newData); await saveRondas(project.id,newData); };

  const abrirDia=(dataStr)=>{
    const ex=(data.registros||[]).find(r=>r.data===dataStr);
    setDiaAtual(ex||{data:dataStr,executor:"",kmInicial:"",kmFinal:"",marcacoes:{},slots:[...(data.slots||SLOTS_DEFAULT)]});
    setScreen("dia");
  };

  const salvarDia=async(reg)=>{
    setSaving(true);
    const registros=[...(data.registros||[]).filter(r=>r.data!==reg.data),reg].sort((a,b)=>b.data.localeCompare(a.data));
    await save({...data,registros});
    setSaving(false);
  };

  const marcarSlot=async(hora,status)=>{
    const novo={...diaAtual,marcacoes:{...diaAtual.marcacoes,[hora]:{status,obs:(diaAtual.marcacoes?.[hora]?.obs||""),hora:nowTime()}}};
    setDiaAtual(novo); await salvarDia(novo);
  };

  const excluirSlotDia=async(hora)=>{
    const m={...diaAtual.marcacoes}; delete m[hora];
    const slots=(diaAtual.slots||SLOTS_DEFAULT).filter(h=>h!==hora);
    const novo={...diaAtual,slots,marcacoes:m};
    setDiaAtual(novo); await salvarDia(novo); setConfirmDelSlot(null);
  };

  const excluirSlotGlobal=async(hora)=>{
    await save({...data,slots:(data.slots||SLOTS_DEFAULT).filter(h=>h!==hora)});
    setConfirmDelSlot(null);
  };

  const adicionarSlot=async(hora)=>{
    if(!hora) return;
    await save({...data,slots:[...new Set([...(data.slots||SLOTS_DEFAULT),hora])].sort()});
  };

  if(loading) return(
    <div style={{...S.page,alignItems:"center",justifyContent:"center"}}>
      <div style={{textAlign:"center"}}><div style={{fontSize:30,marginBottom:10}}>🚗</div><div style={{fontSize:13,...S.txt2}}>Carregando...</div></div>
    </div>
  );

  // ── Tela do dia
  if(screen==="dia"&&diaAtual){
    const slots=diaAtual.slots||data.slots||SLOTS_DEFAULT;
    const feitos=slots.filter(h=>diaAtual.marcacoes?.[h]?.status==="feito").length;
    const naoFeito=slots.filter(h=>diaAtual.marcacoes?.[h]?.status==="nao_feito").length;
    const pct=slots.length?Math.round((feitos/slots.length)*100):0;
    const pctColor=pct>=90?"#22c55e":pct>=60?"#f59e0b":"#ef4444";
    const colabs=equipe.filter(c=>{const g=(c.cargo||"").toLowerCase(); return g.includes("vspp");});
    return(
      <div style={S.page}>
        <div style={S.wrap}>
          <div style={{display:"flex",alignItems:"center",gap:10,padding:"14px 16px",borderBottom:`1px solid ${dark?"#0a0f1e":"#e2e8f0"}`}}>
            <button onClick={()=>setScreen("list")} style={S.backBtn}>← Voltar</button>
            <div style={{flex:1}}>
              <div style={{fontSize:14,fontWeight:800,...S.txt}}>🚗 Ronda VSPP — {fmtDate(diaAtual.data)}</div>
              <div style={{fontSize:11,...S.txt2}}>P601 · Diurno · <span style={{color:pctColor,fontWeight:700}}>{pct}% executado</span></div>
            </div>
            <button onClick={()=>gerarPDFRondaVSPP(project,diaAtual,data.registros||[])}
              style={{...S.btnSm,color:"#0f6e56",borderColor:"#0f6e5644",fontWeight:700,padding:"7px 10px"}}>📄 PDF</button>
          </div>

          <div style={{padding:"12px 16px",display:"flex",flexDirection:"column",gap:10}}>
            {/* Executor */}
            <div style={S.card}>
              <label style={S.lbl}>Executor da Ronda *</label>
              {colabs.length>0?(
                <select value={diaAtual.executor} onChange={e=>{const n={...diaAtual,executor:e.target.value};setDiaAtual(n);salvarDia(n);}} style={{...S.inp}}>
                  <option value="">— Selecione quem está em campo —</option>
                  {colabs.map(c=><option key={c.id||c.nome} value={c.nome}>{c.nome} · {c.cargo}</option>)}
                  <option value="__outro">Outro (digitar abaixo)</option>
                </select>
              ):(
                <input value={diaAtual.executor} onChange={e=>setDiaAtual(p=>({...p,executor:e.target.value}))}
                  onBlur={()=>salvarDia(diaAtual)} placeholder="Nome do agente..." style={S.inp}/>
              )}
              {diaAtual.executor==="__outro"&&(
                <input style={{...S.inp,marginTop:8}} placeholder="Nome do agente..."
                  onChange={e=>setDiaAtual(p=>({...p,executor:e.target.value}))} onBlur={()=>salvarDia(diaAtual)}/>
              )}
            </div>

            {/* KM */}
            <div style={S.card}>
              <label style={{...S.lbl,marginBottom:10}}>🚗 KM do Turno</label>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
                <div>
                  <label style={S.lbl}>KM Início (1ª ronda)</label>
                  <input type="number" inputMode="decimal" placeholder="Ex: 12450" value={diaAtual.kmInicial}
                    onChange={e=>setDiaAtual(p=>({...p,kmInicial:e.target.value}))}
                    onBlur={()=>salvarDia(diaAtual)} style={S.inp}/>
                </div>
                <div>
                  <label style={S.lbl}>KM Fim (última ronda)</label>
                  <input type="number" inputMode="decimal" placeholder="Ex: 12520" value={diaAtual.kmFinal}
                    onChange={e=>setDiaAtual(p=>({...p,kmFinal:e.target.value}))}
                    onBlur={()=>salvarDia(diaAtual)} style={S.inp}/>
                </div>
              </div>
              {diaAtual.kmInicial&&diaAtual.kmFinal&&(
                <div style={{marginTop:8,padding:"6px 10px",background:dark?"#021a0d":"#f0fdf4",borderRadius:6,fontSize:12,color:"#0f6e56",fontWeight:700}}>
                  🚗 KM percorrido no turno: {Math.abs(parseFloat(diaAtual.kmFinal)-parseFloat(diaAtual.kmInicial)).toFixed(1)} km
                </div>
              )}
            </div>

            {/* Mapa */}
            <div style={S.card}>
              <label style={{...S.lbl,marginBottom:8}}>🗺️ Rota de Ronda VSPP</label>
              <img src={`data:image/jpeg;base64,${MAPA_B64}`} alt="Rota de Ronda VSPP"
                style={{width:"100%",borderRadius:8,border:`1px solid ${dark?"#1e293b":"#e2e8f0"}`}}/>
            </div>

            {/* Slots */}
            <div style={{fontSize:11,...S.txt2,fontWeight:700,textTransform:"uppercase",letterSpacing:.8}}>Horários ({slots.length}) · Turno Diurno</div>
            {slots.map(h=>{
              const m=diaAtual.marcacoes?.[h];
              const st=m?.status;
              const borderColor=st==="feito"?"#22c55e44":st==="nao_feito"?"#ef444444":dark?"#0f172a":"#e2e8f0";
              return(
                <div key={h} style={{...S.card,border:`1px solid ${borderColor}`}}>
                  <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:8}}>
                    <span style={{fontSize:18,fontWeight:900,letterSpacing:1,...S.txt,minWidth:52}}>{h}</span>
                    <div style={{display:"flex",gap:6,flex:1,flexWrap:"wrap"}}>
                      <button onClick={()=>marcarSlot(h,"feito")}
                        style={{...S.btnSm,flex:1,background:st==="feito"?"#021a0d":"transparent",borderColor:st==="feito"?"#22c55e66":dark?"#0f172a":"#e2e8f0",color:st==="feito"?"#22c55e":dark?"#94a3b8":"#64748b",fontWeight:st==="feito"?700:600,padding:"9px"}}>
                        ✓ Feito{m?.hora?` (${m.hora})`:""}
                      </button>
                      <button onClick={()=>marcarSlot(h,"nao_feito")}
                        style={{...S.btnSm,flex:1,background:st==="nao_feito"?"#1a0202":"transparent",borderColor:st==="nao_feito"?"#ef444466":dark?"#0f172a":"#e2e8f0",color:st==="nao_feito"?"#ef4444":dark?"#94a3b8":"#64748b",fontWeight:st==="nao_feito"?700:600,padding:"9px"}}>
                        ✗ Não feito
                      </button>
                    </div>
                    {adminAuth&&<button onClick={()=>setConfirmDelSlot({hora:h,tipo:"dia"})}
                      style={{...S.btnSm,color:"#94a3b8",padding:"6px 8px",flexShrink:0}}>🗑</button>}
                  </div>
                  <input value={m?.obs||""} onChange={e=>{
                    const mNew={...diaAtual.marcacoes,[h]:{...(diaAtual.marcacoes?.[h]||{}),obs:e.target.value}};
                    setDiaAtual(p=>({...p,marcacoes:mNew}));
                  }} onBlur={()=>salvarDia(diaAtual)} placeholder="Observação (opcional)..."
                    style={{...S.inp,fontSize:12,padding:"7px 10px"}}/>
                </div>
              );
            })}

            {/* Resumo */}
            <div style={{...S.card,background:dark?"#021a0d":"#f0fdf4",border:"1px solid #22c55e33"}}>
              <div style={{display:"flex",justifyContent:"space-around",textAlign:"center"}}>
                <div><div style={{fontSize:22,fontWeight:900,color:"#22c55e"}}>{feitos}</div><div style={{fontSize:11,...S.txt2}}>Feitas</div></div>
                <div><div style={{fontSize:22,fontWeight:900,color:"#ef4444"}}>{naoFeito}</div><div style={{fontSize:11,...S.txt2}}>Não feitas</div></div>
                <div><div style={{fontSize:22,fontWeight:900,color:"#94a3b8"}}>{slots.length-feitos-naoFeito}</div><div style={{fontSize:11,...S.txt2}}>Pendentes</div></div>
                <div><div style={{fontSize:22,fontWeight:900,color:pctColor}}>{pct}%</div><div style={{fontSize:11,...S.txt2}}>Executado</div></div>
              </div>
            </div>
            {saving&&<div style={{textAlign:"center",fontSize:12,...S.txt2}}>Salvando...</div>}
          </div>
        </div>
        {confirmDelSlot&&(
          <div onClick={()=>setConfirmDelSlot(null)} style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.75)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:999,padding:16}}>
            <div onClick={e=>e.stopPropagation()} style={{...S.card,maxWidth:320,width:"100%",textAlign:"center"}}>
              <div style={{fontSize:16,fontWeight:800,...S.txt,marginBottom:6}}>Excluir {confirmDelSlot.hora}?</div>
              <div style={{fontSize:12,...S.txt2,marginBottom:16}}>{confirmDelSlot.tipo==="global"?"Remove de todos os dias futuros.":"Remove apenas hoje."}</div>
              <div style={{display:"flex",gap:8}}>
                <button onClick={()=>setConfirmDelSlot(null)} style={{...S.btnSec,flex:1,fontSize:13}}>Cancelar</button>
                <button onClick={()=>confirmDelSlot.tipo==="global"?excluirSlotGlobal(confirmDelSlot.hora):excluirSlotDia(confirmDelSlot.hora)}
                  style={{...S.btn,flex:1,fontSize:13,background:"linear-gradient(135deg,#dc2626,#991b1b)"}}>Excluir</button>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  // ── Lista de dias
  const registros=(data.registros||[]).slice().sort((a,b)=>b.data.localeCompare(a.data));
  const hoje=todayStr();
  const temHoje=registros.some(r=>r.data===hoje);
  return(
    <div style={S.page}>
      <div style={S.wrap}>
        <div style={{display:"flex",alignItems:"center",gap:10,padding:"14px 16px",borderBottom:`1px solid ${dark?"#0a0f1e":"#e2e8f0"}`}}>
          <button onClick={onBack} style={S.backBtn}>← Voltar</button>
          <div style={{flex:1}}>
            <div style={{fontSize:14,fontWeight:800,...S.txt}}>🚗 Ronda VSPP</div>
            <div style={{fontSize:11,...S.txt2}}>P601 · Golgi Cajamar · Turno Diurno · {data.slots?.length||15} horários</div>
          </div>
        </div>
        <div style={{padding:"12px 16px",display:"flex",flexDirection:"column",gap:10}}>
          <div style={S.card}>
            <label style={{...S.lbl,marginBottom:8}}>🗺️ Rota de Ronda</label>
            <img src={`data:image/jpeg;base64,${MAPA_B64}`} alt="Rota de Ronda VSPP" style={{width:"100%",borderRadius:8}}/>
          </div>

          {!temHoje&&<button onClick={()=>abrirDia(hoje)} style={{...S.btn,fontSize:15,padding:"15px"}}>🚗 Iniciar Ronda de Hoje</button>}
          {temHoje&&<button onClick={()=>abrirDia(hoje)} style={{...S.btn,fontSize:14}}>▶ Continuar Ronda de Hoje</button>}

          {adminAuth&&(
            <div style={{...S.card,border:`1px dashed ${dark?"#1e293b":"#e2e8f0"}`}}>
              <div style={{fontSize:11,...S.txt2,fontWeight:700,marginBottom:8}}>⚙️ Gerenciar Horários (Gerencial)</div>
              <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:8}}>
                {(data.slots||SLOTS_DEFAULT).map(h=>(
                  <div key={h} style={{display:"flex",alignItems:"center",gap:4,background:dark?"#0a0f1e":"#f1f5f9",borderRadius:6,padding:"4px 8px"}}>
                    <span style={{fontSize:12,...S.txt,fontWeight:700}}>{h}</span>
                    <button onClick={()=>setConfirmDelSlot({hora:h,tipo:"global"})} style={{background:"transparent",border:"none",color:"#94a3b8",cursor:"pointer",fontSize:14,lineHeight:1}}>×</button>
                  </div>
                ))}
              </div>
              <div style={{display:"flex",gap:8}}>
                <input id="novo-slot-vspp" type="time" style={{...S.inp,flex:1,padding:"7px 10px"}}/>
                <button onClick={()=>adicionarSlot(document.getElementById("novo-slot-vspp")?.value)}
                  style={{...S.btnSm,color:"#0f6e56",borderColor:"#0f6e5644",fontWeight:700,padding:"7px 12px",whiteSpace:"nowrap"}}>+ Adicionar</button>
              </div>
            </div>
          )}

          <div style={{fontSize:11,...S.txt2,fontWeight:700,textTransform:"uppercase",letterSpacing:.8,marginTop:4}}>Histórico ({registros.length})</div>
          {registros.length===0&&<div style={{textAlign:"center",padding:"30px 0",...S.txt2,fontSize:13}}>Nenhuma ronda registrada ainda.</div>}
          {registros.map(r=>{
            const slts=r.slots||data.slots||SLOTS_DEFAULT;
            const f=slts.filter(h=>r.marcacoes?.[h]?.status==="feito").length;
            const nf=slts.filter(h=>r.marcacoes?.[h]?.status==="nao_feito").length;
            const p=slts.length?Math.round((f/slts.length)*100):0;
            const c=p>=90?"#22c55e":p>=60?"#f59e0b":"#ef4444";
            return(
              <div key={r.data} onClick={()=>abrirDia(r.data)} style={{...S.card,cursor:"pointer",borderColor:c+"44"}}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:4}}>
                  <span style={{fontSize:13,fontWeight:800,...S.txt}}>{fmtDate(r.data)}</span>
                  <span style={{fontSize:14,fontWeight:900,color:c}}>{p}%</span>
                </div>
                <div style={{fontSize:11,...S.txt2}}>{r.executor||"Executor não informado"} · ✓ {f} · ✗ {nf}</div>
                {(r.kmInicial||r.kmFinal)&&<div style={{fontSize:11,...S.txt2,marginTop:2}}>
                  🚗 {r.kmInicial?`Ini: ${r.kmInicial} km`:""}{r.kmInicial&&r.kmFinal?" · ":""}{r.kmFinal?`Fim: ${r.kmFinal} km`:""}
                </div>}
                <div style={{marginTop:6,height:3,background:dark?"#0f172a":"#e2e8f0",borderRadius:2,overflow:"hidden"}}>
                  <div style={{height:"100%",width:`${p}%`,background:c,borderRadius:2}}/>
                </div>
              </div>
            );
          })}
        </div>
      </div>
      {confirmDelSlot&&(
        <div onClick={()=>setConfirmDelSlot(null)} style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.75)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:999,padding:16}}>
          <div onClick={e=>e.stopPropagation()} style={{...S.card,maxWidth:320,width:"100%",textAlign:"center"}}>
            <div style={{fontSize:16,fontWeight:800,...S.txt,marginBottom:6}}>Excluir horário {confirmDelSlot.hora}?</div>
            <div style={{fontSize:12,...S.txt2,marginBottom:16}}>Remove de todos os dias futuros. Histórico já salvo não é afetado.</div>
            <div style={{display:"flex",gap:8}}>
              <button onClick={()=>setConfirmDelSlot(null)} style={{...S.btnSec,flex:1,fontSize:13}}>Cancelar</button>
              <button onClick={()=>excluirSlotGlobal(confirmDelSlot.hora)} style={{...S.btn,flex:1,fontSize:13,background:"linear-gradient(135deg,#dc2626,#991b1b)"}}>Excluir</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
